const menu=document.querySelector('.menu'),nav=document.querySelector('.navlinks');
menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'Close':'Menu';nav.classList.toggle('open',open);if(open)nav.querySelector('a')?.focus();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu?.getAttribute('aria-expanded')==='true'){menu.click();menu.focus();}});
const examples={owed:{question:'Who owes me money?',answer:'Three customers have outstanding invoices in this demonstration.',rows:[['Demo Customer A','R 12,450'],['Demo Customer B','R 8,200'],['Demo Customer C','R 4,750']],closing:'I can prepare a friendly payment reminder for you to review.'},attention:{question:'What needs my attention today?',answer:'Here is a sample overview of items to review.',rows:[['Overdue invoices','3 to review'],['Low-stock products','2 to review'],['Bank transactions','6 to match']],closing:'Choose an item to review before taking any action.'},sales:{question:'How much did I sell this month?',answer:'This sample business recorded R 84,250 in sales this month.',rows:[['Quotes awaiting response','4'],['Invoices issued','18'],['Payments received','R 59,850']],closing:'These figures are demonstration data, not real business results.'},stock:{question:'Do I need to reorder any stock?',answer:'Two sample products are below their reorder levels.',rows:[['M8 bolt packs','8 available'],['Industrial seal kits','3 available']],closing:'I can help prepare a purchase order. You review and confirm before it is completed.'},suppliers:{question:'What do I owe suppliers?',answer:'Two suppliers have unpaid amounts in this sample workspace.',rows:[['Demo Supplier A','R 7,600'],['Demo Supplier B','R 3,450']],closing:'Check invoice due dates before deciding what to pay. No payment has been made.'},quote:{question:'Prepare a quote for 4 bearings.',answer:'Which customer is this for, which bearing should I use and what is the unit price?',rows:[['Quantity','4'],['Customer and product','Details needed'],['Price','Your confirmation needed']],closing:'No quote has been created. Bizzy asks for missing details rather than inventing them.'},invoice:{question:'Show me that invoice.',answer:'Using the invoice already identified in this sample conversation: INV-DEMO-001.',rows:[['Customer','Demo Customer A'],['Outstanding','R 12,450'],['Document','Sample invoice']],closing:'A real request needs an identified invoice or a document reference. This example contains no real customer information.'},reminder:{question:'Prepare a friendly payment reminder.',answer:'Here is a draft for your review: “Hi Demo Customer A, a friendly reminder that invoice INV-DEMO-001 for R 12,450 is outstanding. Please let us know if you need a copy. Thank you.”',rows:[['Status','Draft only'],['Next step','Review, copy and share manually']],closing:'No message has been sent. This is an illustrative demonstration.'}};
document.querySelectorAll('[data-prompt]').forEach(button=>button.addEventListener('click',()=>{const example=examples[button.dataset.prompt];const panel=document.getElementById('bizzy-demo');panel.querySelector('.question').textContent=example.question;panel.querySelector('.answer-text').textContent=example.answer;panel.querySelector('tbody').replaceChildren(...example.rows.map(row=>{const tr=document.createElement('tr');row.forEach(value=>{const td=document.createElement('td');td.textContent=value;tr.append(td);});return tr;}));panel.querySelector('.answer-closing').textContent=example.closing;document.querySelectorAll('[data-prompt]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));}));
document.querySelectorAll('[data-year]').forEach(el=>el.textContent=new Date().getFullYear());

nav?.addEventListener('click',event=>{if(event.target.closest('a')&&menu.getAttribute('aria-expanded')==='true'){menu.click();}});
window.matchMedia('(min-width:901px)').addEventListener('change',event=>{if(event.matches&&menu?.getAttribute('aria-expanded')==='true')menu.click();});
